11	// ============================================================
12	// GELU 算子 op_host
13	// Host 端: tiling 计算 + EXEC_KERNEL_CMD kernel 启动
14	// ============================================================
15	
16	#include "torch_kernel_helper.h"
17	#include "tiling/platform/platform_ascendc.h"
18	#include "aclrtlaunch_gelu.h"
19	
20	namespace ascend_kernel {
21	
22	constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
23	
24	at::Tensor gelu(const at::Tensor &self, std::string approximate)
25	{
26	    // ---- 输入校验 ----
27	    TORCH_CHECK(self.scalar_type() == at::kHalf ||
28	                self.scalar_type() == at::kBFloat16 ||
29	                self.scalar_type() == at::kFloat,
30	                "gelu: only float16, bfloat16 and float32 are supported, got ", self.scalar_type());
31	    TORCH_CHECK(approximate == "none" || approximate == "tanh",
32	                "gelu: approximate must be 'none' or 'tanh', got ", approximate);
33	
34	    at::Tensor output = at::empty_like(self);
35	
36	    int64_t totalLength = self.numel();
37	    if (totalLength == 0) {
38	        return output;
39	    }
40	
41	    int64_t dtypeSize = self.element_size();
42	    int64_t isBfloat16 = (self.scalar_type() == at::kBFloat16) ? 1 : 0;
43	    // Convert approximate string to int32_t flag: 0=none (exact), 1=tanh
44	    int32_t approximateFlag = (approximate == "tanh") ? 1 : 0;
45	
46	    // ---- 获取硬件参数 ----
47	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
48	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
49	    uint64_t ubSize;
50	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
51	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
52	
53	    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
54	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
55	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
56	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
57	
58	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
59	    int64_t formerNum = usedCoreNum - 1;
60	    int64_t formerLength = totalLengthCoreAlign;
61	    int64_t tailLength = totalLength - formerNum * formerLength;
62	
63	    // ---- UB 级 tiling (核内切分) ----
64	    // bufferCoefficient:
65	    //   fp32: 32 = 8(inQueue*2) + 8(outQueue*2) + 4*4(tempBuf0..3)
66	    //   fp16/bf16: 24 = 4(inQueue*2) + 4(outQueue*2) + 4*4(tempBuf0..3)
67	    int64_t bufferCoefficient = (dtypeSize == 2) ? 24 : 32;
68	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
69	    int64_t alignElements = 32 / dtypeSize;
70	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
71	
72	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
73	
74	    EXEC_KERNEL_CMD(gelu, blockDim,
75	                    self, output,
76	                    formerNum, formerLength, tailLength, tileLength,
77	                    dtypeSize, approximateFlag, isBfloat16);
78	
79	    return output;
80	}
81	
82	}  // namespace ascend_kernel
