10	
11	// ============================================================
12	// GELU operator kernel
13	// Exact:  gelu(x) = 0.5*x + 0.5*|x| * erf_abs(|x|/sqrt(2))
14	// Tanh:   gelu(x) = 0.5*x * (1 + tanh(sqrt(2/pi)*(x+0.044715*x^3)))
15	// Supports float32 directly, float16/bfloat16 via Cast to FP32.
16	// ============================================================
17	
18	#include "kernel_operator.h"
19	
20	constexpr int32_t BUFFER_NUM = 2;
21	
22	// Exact GELU erf constants (Abramowitz & Stegun)
23	constexpr float RCP_SQRT2 = 0.7071067811865476f;
24	constexpr float ERF_P     = 0.3275911f;
25	constexpr float ERF_A1    = 0.254829592f;
26	constexpr float ERF_A2    = -0.284496736f;
27	constexpr float ERF_A3    = 1.421413741f;
28	constexpr float ERF_A4    = -1.453152027f;
29	constexpr float ERF_A5    = 1.061405429f;
30	
31	// Tanh GELU constants
32	constexpr float SQRT_2_OVER_PI = 0.7978845608028654f;
33	constexpr float C_0044715      = 0.044715f;
34	
35	template <typename T>
36	class KernelGelu {
37	public:
38	    __aicore__ inline KernelGelu() {}
39	
40	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
41	                                int64_t formerNum, int64_t formerLength,
42	                                int64_t tailLength, int64_t tileLength,
43	                                int64_t dtypeSize, int32_t approximate)
44	    {
45	        this->tileLength = tileLength;
46	        this->approximate = approximate;
47	
48	        int64_t blockIdx = AscendC::GetBlockIdx();
49	        if (blockIdx < formerNum) {
50	            this->blockLength = formerLength;
51	            int64_t offset = formerLength * blockIdx;
52	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
53	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
54	        } else {
55	            this->blockLength = tailLength;
56	            int64_t tailIdx = blockIdx - formerNum;
57	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
58	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
59	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
60	        }
61	
62	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
63	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
64	        pipe.InitBuffer(tempBuf0, tileLength * sizeof(float));
65	        pipe.InitBuffer(tempBuf1, tileLength * sizeof(float));
66	        pipe.InitBuffer(tempBuf2, tileLength * sizeof(float));
67	        pipe.InitBuffer(tempBuf3, tileLength * sizeof(float));
68	    }
69	
70	    __aicore__ inline void Process()
71	    {
72	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
73	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
74	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
75	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
76	
77	        for (int64_t i = 0; i < tileNum - 1; ++i) {
78	            CopyIn(i, this->tileLength);
79	            Compute(i, this->tileLength);
80	            CopyOut(i, this->tileLength);
81	        }
82	        if (tileNum > 0) {
83	            CopyIn(tileNum - 1, alignedTailLen);
84	            Compute(tileNum - 1, alignedTailLen);
85	            CopyOut(tileNum - 1, alignedTailLen);
86	        }
87	    }
88	
89	private:
90	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
91	    {
92	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
93	        AscendC::DataCopy(xLocal, xGm[progress * this->tileLength], curTileLength);
94	        inQueueX.EnQue(xLocal);
95	    }
96	
97	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
98	    {
99	        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
100	        AscendC::DataCopy(yGm[progress * this->tileLength], yLocal, curTileLength);
101	        outQueueY.FreeTensor(yLocal);
102	    }
103	
104	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
105	    {
106	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
107	        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
108	
109	        if constexpr (sizeof(T) == sizeof(float)) {
110	            // FP32: xLocal is the FP32 input. 3 scratch buffers suffice.
111	            AscendC::LocalTensor<float> b0 = tempBuf0.Get<float>();
112	            AscendC::LocalTensor<float> b1 = tempBuf1.Get<float>();
113	            AscendC::LocalTensor<float> b2 = tempBuf2.Get<float>();
114	            if (this->approximate == 0) {
115	                ComputeExactFP32(xLocal, yLocal, b0, b1, b2, curTileLength);
116	            } else {
117	                ComputeTanhFP32(xLocal, yLocal, b0, b1, b2, curTileLength);
118	            }
119	        } else {
120	            // FP16/BF16: Cast input to FP32 (b0), use 3 scratch buffers (b1,b2,b3),
121	            // result goes to b3 for exact, b0 for tanh. Cast to output.
122	            AscendC::LocalTensor<float> xf = tempBuf0.Get<float>();
123	            AscendC::LocalTensor<float> b1 = tempBuf1.Get<float>();
124	            AscendC::LocalTensor<float> b2 = tempBuf2.Get<float>();
125	            AscendC::LocalTensor<float> b3 = tempBuf3.Get<float>();
126	
127	            AscendC::Cast(xf, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
128	
129	            AscendC::LocalTensor<float> resultBuf;
130	            if (this->approximate == 0) {
131	                ComputeExactHalf(xf, b1, b2, b3, curTileLength);
132	                resultBuf = b3;  // ComputeExactHalf puts result in b3
133	            } else {
134	                ComputeTanhHalf(xf, b1, b2, curTileLength);
135	                resultBuf = xf;  // ComputeTanhHalf puts result in xf (b0)
136	            }
137	            AscendC::Cast(yLocal, resultBuf, AscendC::RoundMode::CAST_ROUND, curTileLength);
138	        }
139	
140	        outQueueY.EnQue<T>(yLocal);
141	        inQueueX.FreeTensor(xLocal);
142	    }
143	
144	    // -------------------------------------------------------------------
145	    // Exact GELU — FP32 path: gelu(x) = 0.5*x + 0.5*|x|*erf_abs(|x|/sqrt2)
146	    // 5 FP32 buffers available: x (VECIN), y (VECOUT), b0, b1, b2 (TBuf).
147	    // -------------------------------------------------------------------
148	    __aicore__ inline void ComputeExactFP32(
149	        AscendC::LocalTensor<float> xf,
150	        AscendC::LocalTensor<float> yf,
151	        AscendC::LocalTensor<float> b0,
152	        AscendC::LocalTensor<float> b1,
153	        AscendC::LocalTensor<float> b2,
154	        int64_t len)
155	    {
156	        // yf = 0.5 * x  (accumulate final result)
157	        AscendC::Muls(yf, xf, 0.5f, len);
158	
159	        // b0 = s = |x| / sqrt(2)
160	        AscendC::Abs(b0, xf, len);
161	        AscendC::Muls(b0, b0, RCP_SQRT2, len);
162	
163	        // b1 = exp(-s^2)
164	        AscendC::Mul(b1, b0, b0, len);
165	        AscendC::Muls(b1, b1, -1.0f, len);
166	        AscendC::Exp(b1, b1, len);
167	
168	        // b0 = t = 1 / (1 + ERF_P * s)
169	        AscendC::Muls(b0, b0, ERF_P, len);
170	        AscendC::Adds(b0, b0, 1.0f, len);
171	        AscendC::Reciprocal(b0, b0, len);
172	
173	        // Horner polynomial in b2
174	        AscendC::Muls(b2, b0, ERF_A5, len);
175	        AscendC::Adds(b2, b2, ERF_A4, len);
176	        AscendC::Mul(b2, b2, b0, len);
177	        AscendC::Adds(b2, b2, ERF_A3, len);
178	        AscendC::Mul(b2, b2, b0, len);
179	        AscendC::Adds(b2, b2, ERF_A2, len);
180	        AscendC::Mul(b2, b2, b0, len);
181	        AscendC::Adds(b2, b2, ERF_A1, len);
182	        AscendC::Mul(b2, b2, b0, len);
183	
184	        // b2 = erf_abs = 1 - poly * exp(-s^2)
185	        AscendC::Mul(b2, b2, b1, len);
186	        AscendC::Muls(b2, b2, -1.0f, len);
187	        AscendC::Adds(b2, b2, 1.0f, len);
188	
189	        // b0 = |x| (xf still holds original x; recompute |x|)
190	        AscendC::Abs(b0, xf, len);
191	        // b0 = 0.5 * |x| * erf_abs
192	        AscendC::Muls(b0, b0, 0.5f, len);
193	        AscendC::Mul(b0, b0, b2, len);
194	        // yf = 0.5*x + 0.5*|x|*erf_abs = gelu
195	        AscendC::Add(yf, yf, b0, len);
196	    }
197	
198	    // -------------------------------------------------------------------
199	    // Exact GELU — half path: input in xf(b0), result in b3.
200	    // 4 FP32 buffers: xf (in), b1, b2, b3 (result).
201	    //
202	    // Key trick: save 0.5*x in b3 early.  Recover |x| = 2 * Abs(b3).
203	    // -------------------------------------------------------------------
204	    __aicore__ inline void ComputeExactHalf(
205	        AscendC::LocalTensor<float> xf,
206	        AscendC::LocalTensor<float> b1,
207	        AscendC::LocalTensor<float> b2,
208	        AscendC::LocalTensor<float> b3,
209	        int64_t len)
210	    {
211	        // b3 = 0.5 * x   (save for final accumulate; also source of |x|)
212	        AscendC::Muls(b3, xf, 0.5f, len);
213	
214	        // b1 = |x| = 2 * |0.5*x|
215	        AscendC::Abs(b1, b3, len);
216	        AscendC::Muls(b1, b1, 2.0f, len);
217	
218	        // b2 = s = |x| / sqrt(2)
219	        AscendC::Muls(b2, b1, RCP_SQRT2, len);
220	
221	        // b1 = exp(-s^2)
222	        AscendC::Mul(b1, b2, b2, len);
223	        AscendC::Muls(b1, b1, -1.0f, len);
224	        AscendC::Exp(b1, b1, len);
225	
226	        // b2 = t = 1 / (1 + ERF_P * s)
227	        AscendC::Muls(b2, b2, ERF_P, len);
228	        AscendC::Adds(b2, b2, 1.0f, len);
229	        AscendC::Reciprocal(b2, b2, len);
230	
231	        // Horner polynomial in xf (overwrite input x, no longer needed)
232	        AscendC::Muls(xf, b2, ERF_A5, len);
233	        AscendC::Adds(xf, xf, ERF_A4, len);
234	        AscendC::Mul(xf, xf, b2, len);
235	        AscendC::Adds(xf, xf, ERF_A3, len);
236	        AscendC::Mul(xf, xf, b2, len);
237	        AscendC::Adds(xf, xf, ERF_A2, len);
238	        AscendC::Mul(xf, xf, b2, len);
239	        AscendC::Adds(xf, xf, ERF_A1, len);
240	        AscendC::Mul(xf, xf, b2, len);
241	
242	        // xf = erf_abs = 1 - poly * exp(-s^2)
243	        AscendC::Mul(xf, xf, b1, len);
244	        AscendC::Muls(xf, xf, -1.0f, len);
245	        AscendC::Adds(xf, xf, 1.0f, len);
246	
247	        // b1 = 0.5 * |x| * erf_abs
248	        //     = |0.5*x| * erf_abs   (since Abs(b3) = |0.5*x| = 0.5*|x|)
249	        AscendC::Abs(b1, b3, len);
250	        AscendC::Mul(b1, b1, xf, len);
251	
252	        // b3 = 0.5*x + 0.5*|x|*erf_abs = gelu
253	        AscendC::Add(b3, b3, b1, len);
254	    }
255	
256	    // -------------------------------------------------------------------
257	    // Tanh GELU — FP32 path
258	    // -------------------------------------------------------------------
259	    __aicore__ inline void ComputeTanhFP32(
260	        AscendC::LocalTensor<float> xf,
261	        AscendC::LocalTensor<float> yf,
262	        AscendC::LocalTensor<float> b0,
263	        AscendC::LocalTensor<float> b1,
264	        AscendC::LocalTensor<float> b2,
265	        int64_t len)
266	    {
267	        // b0 = x^2
268	        AscendC::Mul(b0, xf, xf, len);
269	        // b0 = x^3
270	        AscendC::Mul(b0, b0, xf, len);
271	        // b0 = 0.044715 * x^3
272	        AscendC::Muls(b0, b0, C_0044715, len);
273	        // b0 = x + 0.044715 * x^3
274	        AscendC::Add(b0, xf, b0, len);
275	        // b0 = sqrt(2/pi) * (x + 0.044715 * x^3)
276	        AscendC::Muls(b0, b0, SQRT_2_OVER_PI, len);
277	
278	        // b1 = tanh(b0)
279	        AscendC::Tanh(b1, b0, len);
280	        // b1 = 1 + tanh(b0)
281	        AscendC::Adds(b1, b1, 1.0f, len);
282	        // yf = 0.5 * x
283	        AscendC::Muls(yf, xf, 0.5f, len);
284	        // yf = 0.5*x * (1+tanh(...)) = gelu
285	        AscendC::Mul(yf, yf, b1, len);
286	    }
287	
288	    // -------------------------------------------------------------------
289	    // Tanh GELU — half path: input in xf(b0), result in xf(b0).
290	    // -------------------------------------------------------------------
291	    __aicore__ inline void ComputeTanhHalf(
292	        AscendC::LocalTensor<float> xf,
293	        AscendC::LocalTensor<float> b1,
294	        AscendC::LocalTensor<float> b2,
295	        int64_t len)
296	    {
297	        // b1 = x^2
298	        AscendC::Mul(b1, xf, xf, len);
299	        // b1 = x^3
300	        AscendC::Mul(b1, b1, xf, len);
301	        // b1 = 0.044715 * x^3
302	        AscendC::Muls(b1, b1, C_0044715, len);
303	        // b1 = x + 0.044715 * x^3
304	        AscendC::Add(b1, xf, b1, len);
305	        // b1 = sqrt(2/pi) * (x + 0.044715 * x^3)
306	        AscendC::Muls(b1, b1, SQRT_2_OVER_PI, len);
307	
308	        // b2 = tanh(b1)
309	        AscendC::Tanh(b2, b1, len);
310	        // b2 = 1 + tanh(b1)
311	        AscendC::Adds(b2, b2, 1.0f, len);
312	        // xf = 0.5 * x  (overwrite input)
313	        AscendC::Muls(xf, xf, 0.5f, len);
314	        // xf = 0.5*x * (1+tanh(...)) = gelu
315	        AscendC::Mul(xf, xf, b2, len);
316	    }
317	
318	private:
319	    AscendC::TPipe pipe;
320	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
321	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
322	    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBuf0;
323	    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBuf1;
324	    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBuf2;
325	    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBuf3;
326	    AscendC::GlobalTensor<T> xGm;
327	    AscendC::GlobalTensor<T> yGm;
328	    int64_t blockLength;
329	    int64_t tileLength;
330	    int32_t approximate;
331	};
332	
333	extern "C" __global__ __aicore__ void gelu(GM_ADDR x, GM_ADDR y,
334	                                            int64_t formerNum, int64_t formerLength,
335	                                            int64_t tailLength, int64_t tileLength,
336	                                            int64_t dtypeSize, int32_t approximate,
337	                                            int64_t isBfloat16)
338	{
339	    if (isBfloat16) {
340	        KernelGelu<bfloat16_t> op;
341	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength, dtypeSize, approximate);
342	        op.Process();
343	    } else if (dtypeSize == 2) {
344	        KernelGelu<half> op;
345	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength, dtypeSize, approximate);
346	        op.Process();
347	    } else {
348	        KernelGelu<float> op;
349	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength, dtypeSize, approximate);
350	        op.Process();
351	    }
352	}
