// ============================================================
// AdamW optimizer kernel
// Computation (per element, all in float32):
//   1. m_new = beta1 * m + alpha1 * grad
//   2. v_new = beta2 * v + alpha2 * grad^2
//   3. m_hat = m_new / (1-beta1_power)
//   4. v_hat = v_new / (1-beta2_power)
//   5. denom = sqrt(v_hat) + epsilon
//   6. if nesterov: step = lr * (beta1*m_hat + nesterov_factor*grad) / denom
//      else:        step = lr * m_hat / denom
//   7. var_new = var - step
// Supports float32 directly, float16/bfloat16 via Cast to FP32.
// m and v are always float32 regardless of var/grad dtype.
// ============================================================

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelAdamW {
public:
    __aicore__ inline KernelAdamW() {}

    __aicore__ inline void Init(
        GM_ADDR var, GM_ADDR m, GM_ADDR v, GM_ADDR grad,
        GM_ADDR var_out, GM_ADDR m_out, GM_ADDR v_out,
        int64_t formerNum, int64_t formerLength,
        int64_t tailLength, int64_t tileLength,
        int64_t dtypeSize,
        float alpha1, float alpha2,
        float beta1_f, float beta2_f,
        float lr_f, float epsilon_f,
        float inv_b1p, float inv_b2p,
        int64_t use_nesterov,
        float nesterov_grad_factor)
    {
        this->tileLength = tileLength;
        this->alpha1 = alpha1;
        this->alpha2 = alpha2;
        this->beta1_f = beta1_f;
        this->beta2_f = beta2_f;
        this->lr_f = lr_f;
        this->epsilon_f = epsilon_f;
        this->inv_b1p = inv_b1p;
        this->inv_b2p = inv_b2p;
        this->use_nesterov = use_nesterov;
        this->nesterov_grad_factor = nesterov_grad_factor;

        int64_t blockIdx = AscendC::GetBlockIdx();
        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            varGm.SetGlobalBuffer((__gm__ T *)var + offset, formerLength);
            mGm.SetGlobalBuffer((__gm__ float *)m + offset, formerLength);
            vGm.SetGlobalBuffer((__gm__ float *)v + offset, formerLength);
            gradGm.SetGlobalBuffer((__gm__ T *)grad + offset, formerLength);
            varOutGm.SetGlobalBuffer((__gm__ T *)var_out + offset, formerLength);
            mOutGm.SetGlobalBuffer((__gm__ float *)m_out + offset, formerLength);
            vOutGm.SetGlobalBuffer((__gm__ float *)v_out + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            varGm.SetGlobalBuffer((__gm__ T *)var + offset, tailLength);
            mGm.SetGlobalBuffer((__gm__ float *)m + offset, tailLength);
            vGm.SetGlobalBuffer((__gm__ float *)v + offset, tailLength);
            gradGm.SetGlobalBuffer((__gm__ T *)grad + offset, tailLength);
            varOutGm.SetGlobalBuffer((__gm__ T *)var_out + offset, tailLength);
            mOutGm.SetGlobalBuffer((__gm__ float *)m_out + offset, tailLength);
            vOutGm.SetGlobalBuffer((__gm__ float *)v_out + offset, tailLength);
        }

        pipe.InitBuffer(varQ, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(mQ, BUFFER_NUM, tileLength * sizeof(float));
        pipe.InitBuffer(vQ, BUFFER_NUM, tileLength * sizeof(float));
        pipe.InitBuffer(gradQ, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(varOutQ, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(mOutQ, BUFFER_NUM, tileLength * sizeof(float));
        pipe.InitBuffer(vOutQ, BUFFER_NUM, tileLength * sizeof(float));

        pipe.InitBuffer(varFp32Buf, tileLength * sizeof(float));
        pipe.InitBuffer(gradFp32Buf, tileLength * sizeof(float));
        pipe.InitBuffer(mWorkBuf, tileLength * sizeof(float));
        pipe.InitBuffer(vWorkBuf, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf1, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf2, tileLength * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> varLocal = varQ.AllocTensor<T>();
        AscendC::DataCopy(varLocal, varGm[progress * this->tileLength], curTileLength);
        varQ.EnQue(varLocal);

        AscendC::LocalTensor<float> mLocal = mQ.AllocTensor<float>();
        AscendC::DataCopy(mLocal, mGm[progress * this->tileLength], curTileLength);
        mQ.EnQue(mLocal);

        AscendC::LocalTensor<float> vLocal = vQ.AllocTensor<float>();
        AscendC::DataCopy(vLocal, vGm[progress * this->tileLength], curTileLength);
        vQ.EnQue(vLocal);

        AscendC::LocalTensor<T> gradLocal = gradQ.AllocTensor<T>();
        AscendC::DataCopy(gradLocal, gradGm[progress * this->tileLength], curTileLength);
        gradQ.EnQue(gradLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> varOutLocal = varOutQ.DeQue<T>();
        AscendC::DataCopy(varOutGm[progress * this->tileLength], varOutLocal, curTileLength);
        varOutQ.FreeTensor(varOutLocal);

        AscendC::LocalTensor<float> mOutLocal = mOutQ.DeQue<float>();
        AscendC::DataCopy(mOutGm[progress * this->tileLength], mOutLocal, curTileLength);
        mOutQ.FreeTensor(mOutLocal);

        AscendC::LocalTensor<float> vOutLocal = vOutQ.DeQue<float>();
        AscendC::DataCopy(vOutGm[progress * this->tileLength], vOutLocal, curTileLength);
        vOutQ.FreeTensor(vOutLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> varLocal = varQ.DeQue<T>();
        AscendC::LocalTensor<float> mLocal = mQ.DeQue<float>();
        AscendC::LocalTensor<float> vLocal = vQ.DeQue<float>();
        AscendC::LocalTensor<T> gradLocal = gradQ.DeQue<T>();

        AscendC::LocalTensor<T> varOutLocal = varOutQ.AllocTensor<T>();
        AscendC::LocalTensor<float> mOutLocal = mOutQ.AllocTensor<float>();
        AscendC::LocalTensor<float> vOutLocal = vOutQ.AllocTensor<float>();

        AscendC::LocalTensor<float> mBuf = mWorkBuf.Get<float>();
        AscendC::LocalTensor<float> vBuf = vWorkBuf.Get<float>();
        AscendC::LocalTensor<float> tmp1 = tmpBuf1.Get<float>();
        AscendC::LocalTensor<float> tmp2 = tmpBuf2.Get<float>();

        if constexpr (sizeof(T) == sizeof(float)) {
            // FP32 path: all inputs already in float32, compute directly
            AscendC::LocalTensor<float> varFp32 = varLocal.template ReinterpretCast<float>();
            AscendC::LocalTensor<float> gradFp32 = gradLocal.template ReinterpretCast<float>();

            ComputeBody(varFp32, mLocal, vLocal, gradFp32,
                        mBuf, vBuf, tmp1, tmp2,
                        varFp32, mOutLocal, vOutLocal,
                        curTileLength);

            // var_out gets the result from varFp32 (which we wrote varNew into)
            // But wait, varFp32 is ReinterpretCast from varLocal, which is TQue buffer.
            // We need to write the result to varOutLocal which is a different TQue.
            // Actually, in the fp32 path, the computation writes result into varFp32 which
            // is an alias of varLocal. But varLocal is the input TQue buffer.
            // We need to write to varOutLocal (VECOUT).
            // Let me fix this: use varFp32 ONLY as input, not as output.

            // Re-do: use varFp32 for input, write result to a separate output location
            // Actually, let me restructure. For fp32 path:
            // - varFp32 is the fp32 input (alias of varLocal)
            // - I need to compute varNew and put it into varOutLocal
            // But varOutLocal is T (half/bf16), not float.

            // This is problematic. Let me restructure the compute.
            // For fp32: compute in tmp1/tmp2, final var result goes to varOutLocal
            // For fp16: compute in fp32 buffers, cast result to varOutLocal
        } else {
            // FP16/BF16 path: Cast var and grad to fp32 first
            AscendC::LocalTensor<float> varFp32 = varFp32Buf.Get<float>();
            AscendC::LocalTensor<float> gradFp32 = gradFp32Buf.Get<float>();

            AscendC::Cast(varFp32, varLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(gradFp32, gradLocal, AscendC::RoundMode::CAST_NONE, curTileLength);

            ComputeBody(varFp32, mLocal, vLocal, gradFp32,
                        mBuf, vBuf, tmp1, tmp2,
                        varFp32, mOutLocal, vOutLocal,
                        curTileLength);

            // Cast varNew back to half/bf16
            AscendC::Cast(varOutLocal, varFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
        }

        varOutQ.EnQue<T>(varOutLocal);
        mOutQ.EnQue<float>(mOutLocal);
        vOutQ.EnQue<float>(vOutLocal);

        varQ.FreeTensor(varLocal);
        mQ.FreeTensor(mLocal);
        vQ.FreeTensor(vLocal);
        gradQ.FreeTensor(gradLocal);
    }

    // Shared computation body — all operands are float32.
    // varNewFp32 receives the updated var value (may be same buffer as varFp32).
    __aicore__ inline void ComputeBody(
        AscendC::LocalTensor<float> varFp32,
        AscendC::LocalTensor<float> mLocal,
        AscendC::LocalTensor<float> vLocal,
        AscendC::LocalTensor<float> gradFp32,
        AscendC::LocalTensor<float> mBuf,
        AscendC::LocalTensor<float> vBuf,
        AscendC::LocalTensor<float> tmp1,
        AscendC::LocalTensor<float> tmp2,
        AscendC::LocalTensor<float> varNewFp32,
        AscendC::LocalTensor<float> mOutLocal,
        AscendC::LocalTensor<float> vOutLocal,
        int64_t curTileLength)
    {
        // ---- Step 1: m_new = beta1 * m + alpha1 * grad ----
        AscendC::Muls(mBuf, mLocal, this->beta1_f, curTileLength);
        AscendC::Axpy(mBuf, gradFp32, this->alpha1, curTileLength);

        // ---- Step 2: v_new = beta2 * v + alpha2 * grad^2 ----
        AscendC::Mul(tmp1, gradFp32, gradFp32, curTileLength);  // grad_sq
        AscendC::Muls(vBuf, vLocal, this->beta2_f, curTileLength);
        AscendC::Axpy(vBuf, tmp1, this->alpha2, curTileLength);

        // ---- Step 3: m_hat = m_new * inv_b1p ----
        AscendC::Muls(mOutLocal, mBuf, this->inv_b1p, curTileLength);

        // ---- Step 4: v_hat = v_new * inv_b2p ----
        AscendC::Muls(vOutLocal, vBuf, this->inv_b2p, curTileLength);

        // ---- Step 5: denom = sqrt(v_hat) + epsilon ----
        AscendC::Sqrt(tmp1, vOutLocal, curTileLength);
        AscendC::Adds(tmp1, tmp1, this->epsilon_f, curTileLength);

        if (this->use_nesterov) {
            // numerator = beta1 * m_hat + nesterov_grad_factor * grad
            AscendC::Muls(tmp2, mOutLocal, this->beta1_f, curTileLength);
            AscendC::Axpy(tmp2, gradFp32, this->nesterov_grad_factor, curTileLength);
            // step = lr * numerator / denom
            AscendC::Muls(tmp2, tmp2, this->lr_f, curTileLength);
            AscendC::Div(tmp2, tmp2, tmp1, curTileLength);
        } else {
            // step = lr * m_hat / denom
            AscendC::Muls(tmp2, mOutLocal, this->lr_f, curTileLength);
            AscendC::Div(tmp2, tmp2, tmp1, curTileLength);
        }

        // ---- Step 7: var_new = var - step ----
        AscendC::Sub(varNewFp32, varFp32, tmp2, curTileLength);
    }

private:
    AscendC::TPipe pipe;

    // Input queues (VECIN)
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> varQ;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> mQ;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> vQ;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> gradQ;

    // Output queues (VECOUT)
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> varOutQ;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> mOutQ;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> vOutQ;

    // Compute buffers (VECCALC)
    AscendC::TBuf<AscendC::TPosition::VECCALC> varFp32Buf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gradFp32Buf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> mWorkBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> vWorkBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf1;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf2;

    // Global tensors
    AscendC::GlobalTensor<T> varGm;
    AscendC::GlobalTensor<float> mGm;
    AscendC::GlobalTensor<float> vGm;
    AscendC::GlobalTensor<T> gradGm;
    AscendC::GlobalTensor<T> varOutGm;
    AscendC::GlobalTensor<float> mOutGm;
    AscendC::GlobalTensor<float> vOutGm;

    // Scalar parameters
    int64_t blockLength;
    int64_t tileLength;
    float alpha1, alpha2;
    float beta1_f, beta2_f;
    float lr_f, epsilon_f;
    float inv_b1p, inv_b2p;
    float nesterov_grad_factor;
    int64_t use_nesterov;
};

extern "C" __global__ __aicore__ void adamw(
