// ============================================================
// AdamW 算子 op_host
// Host 端: tiling 计算 + EXEC_KERNEL_CMD kernel 启动
// ============================================================

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_adamw.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

std::vector<at::Tensor> adamw(
    const at::Tensor &var,
    const at::Tensor &m,
    const at::Tensor &v,
    const at::Tensor &grad,
    double beta1_power,
    double beta2_power,
    double lr,
    double beta1,
    double beta2,
    double epsilon,
    bool use_locking,
    bool use_nesterov)
{
    // ---- 输入校验 ----
    TORCH_CHECK(var.scalar_type() == at::kHalf ||
                var.scalar_type() == at::kBFloat16 ||
                var.scalar_type() == at::kFloat,
                "adamw: only float16, bfloat16 and float32 are supported for var, got ",
                var.scalar_type());
    TORCH_CHECK(m.scalar_type() == at::kFloat,
                "adamw: m must be float32, got ", m.scalar_type());
    TORCH_CHECK(v.scalar_type() == at::kFloat,
                "adamw: v must be float32, got ", v.scalar_type());
    TORCH_CHECK(grad.scalar_type() == var.scalar_type(),
                "adamw: grad must have same dtype as var");

    auto var_contig = var.contiguous();
    auto m_contig = m.contiguous();
    auto v_contig = v.contiguous();
    auto grad_contig = grad.contiguous();

    int64_t totalLength = var_contig.numel();
    if (totalLength == 0) {
        return {at::empty_like(var_contig),
                at::empty_like(m_contig),
                at::empty_like(v_contig)};
    }

    // Allocate output tensors
    at::Tensor var_out = at::empty_like(var_contig);
    at::Tensor m_out = at::empty_like(m_contig);
    at::Tensor v_out = at::empty_like(v_contig);

    int64_t dtypeSize = var_contig.element_size();
    int64_t isBfloat16 = (var_contig.scalar_type() == at::kBFloat16) ? 1 : 0;

    // ---- 获取硬件参数 ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // ---- UB 级 tiling (核内切分) ----
    // bufferCoefficient (per-element bytes in UB):
    //   fp32: 7 queues * BUFFER_NUM(2) * sizeof(float) + 6 TBuf * sizeof(float)
    //         = 7 * 2 * 4 + 6 * 4 = 56 + 24 = 80
    //   fp16/bf16: varQ/gradQ/varOutQ = 3*2*2=12, mQ/mOutQ/vQ/vOutQ = 4*2*4=32, 6 TBuf*4=24
    //              = 12 + 32 + 24 = 68
    int64_t bufferCoefficient = (dtypeSize == 2) ? 68 : 80;
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    int64_t alignElements = 32 / dtypeSize;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength < 1) {
        tileLength = alignElements;
    }

    // ---- Pre-compute derived scalar parameters ----
    float alpha1 = static_cast<float>(1.0 - beta1);
    float alpha2 = static_cast<float>(1.0 - beta2);
    float lr_f = static_cast<float>(lr);
    float epsilon_f = static_cast<float>(epsilon);
    float beta1_f = static_cast<float>(beta1);
    float beta2_f = static_cast<float>(beta2);
    float inv_b1p = static_cast<float>(1.0 / (1.0 - beta1_power));
    float inv_b2p = static_cast<float>(1.0 / (1.0 - beta2_power));
    float nesterov_grad_factor = static_cast<float>(alpha1 / (1.0 - beta1_power));
    int64_t use_nesterov_i = static_cast<int64_t>(use_nesterov ? 1 : 0);

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(adamw, blockDim,
                    var_contig, m_contig, v_contig, grad_contig,
                    var_out, m_out, v_out,
                    formerNum, formerLength, tailLength, tileLength,
                    dtypeSize, isBfloat16,
                    alpha1, alpha2,
                    beta1_f, beta2_f,
                    lr_f, epsilon_f,
                    inv_b1p, inv_b2p,
                    use_nesterov_i, nesterov_grad_factor);

    return {var_out, m_out, v_out};
}

}  // namespace ascend_kernel
